/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.time.OffsetDateTime;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.alert.AlertDispatcher;
import net.civeira.phylax.feature.observe.alert.AlertRules;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlertStatusOptions;
import net.civeira.phylax.feature.observe.observedalert.domain.gateway.ObservedAlertFilter;
import net.civeira.phylax.feature.observe.observedalert.domain.gateway.ObservedAlertQueryRepositoryGateway;
import net.civeira.phylax.feature.observe.observedalertrule.domain.ObservedAlertRule;
import net.civeira.phylax.feature.observe.observedalertrule.domain.gateway.ObservedAlertRuleFilter;
import net.civeira.phylax.feature.observe.observedalertrule.domain.gateway.ObservedAlertRuleQueryRepositoryGateway;

/** Alerts and rules for the viewer (the api already checked the READ level). */
@ApplicationScoped
@RequiredArgsConstructor
public class ObserveAlerts {

  private static final int MAX = 300;

  /** An alert as the viewer shows it (times in epoch milliseconds). */
  public record AlertRow(String uid, String rule, String trigger, String status, String summary,
      String link, Long firedAt, Long resolvedAt, Long notifiedAt) {}

  /** A rule as the viewer shows it. */
  public record RuleRow(String uid, String name, String trigger, String channel, boolean enabled,
      boolean channelAvailable, boolean muted) {}

  private final ObservedAlertQueryRepositoryGateway alerts;
  private final ObservedAlertRuleQueryRepositoryGateway rules;
  private final AlertDispatcher dispatcher;

  /** Open alerts first, then the most recent; {@code status} FIRING / RESOLVED or empty for all. */
  public Map<String, Object> list(final String status) {
    Map<String, ObservedAlertRule> byUid = rules.list(ObservedAlertRuleFilter.builder().build())
        .stream().collect(Collectors.toMap(ObservedAlertRule::getUid, rule -> rule, (a, b) -> a));
    ObservedAlertFilter.ObservedAlertFilterBuilder filter = ObservedAlertFilter.builder();
    if (null != status && !status.isBlank()) {
      filter.status(ObservedAlertStatusOptions.fromValue(status));
    }
    List<AlertRow> rows = alerts.list(filter.build()).stream().map(alert -> row(alert, byUid))
        .sorted(Comparator.comparing((AlertRow row) -> !"FIRING".equals(row.status()))
            .thenComparing(AlertRow::firedAt, Comparator.nullsLast(Comparator.reverseOrder())))
        .limit(MAX).toList();
    List<RuleRow> ruleRows = byUid.values().stream().map(this::rule)
        .sorted(Comparator.comparing(RuleRow::name)).toList();
    Map<String, Object> result = new LinkedHashMap<>();
    result.put("alerts", rows);
    result.put("rules", ruleRows);
    return result;
  }

  private RuleRow rule(final ObservedAlertRule rule) {
    String channel = AlertRules.value(rule.getChannel());
    boolean muted =
        rule.getMutedUntil().map(until -> until.isAfter(OffsetDateTime.now())).orElse(false);
    return new RuleRow(rule.getUid(), rule.getName(), AlertRules.value(rule.getTrigger()), channel,
        Boolean.TRUE.equals(rule.isEnabled()), dispatcher.available(channel), muted);
  }

  private static AlertRow row(final ObservedAlert alert,
      final Map<String, ObservedAlertRule> rules) {
    ObservedAlertRule rule = rules.get(alert.getRuleUid());
    return new AlertRow(alert.getUid(), null == rule ? alert.getRuleUid() : rule.getName(),
        null == rule ? null : AlertRules.value(rule.getTrigger()), alert.getStatus().name(),
        alert.getSummary(), alert.getLink().orElse(null), millis(alert.getFiredAt()),
        alert.getResolvedAt().map(ObserveAlerts::millis).orElse(null),
        alert.getLastNotifiedAt().map(ObserveAlerts::millis).orElse(null));
  }

  private static Long millis(final OffsetDateTime time) {
    return null == time ? null : time.toInstant().toEpochMilli();
  }
}
